import React, { useState } from 'react';
import './App.css';

// Replace with your API Gateway endpoint URL
const API_ENDPOINT = "https://6vkpjuest4.execute-api.eu-north-1.amazonaws.com/default/secure-upload-auth";

function App() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [successMsg, setSuccessMsg] = useState('');
  const [errorMsg, setErrorMsg] = useState('');

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!file || !name || !email) {
      setErrorMsg('Please fill in all required fields and select a file.');
      return;
    }

    setErrorMsg('');
    setSuccessMsg('');
    setUploading(true);
    setProgress(10);

    try {
      // 1. Request presigned URL from backend
      const res = await fetch(API_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          filename: file.name,
          file_size: file.size,
          uploader_name: name,
          uploader_email: email,
          message: message,
          content_type: file.type || 'application/octet-stream'
        })
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to get upload URL');

      setProgress(40);

      // 2. Upload file directly to S3 using presigned PUT URL
      const uploadRes = await fetch(data.upload_url, {
        method: 'PUT',
        headers: { 'Content-Type': file.type || 'application/octet-stream' },
        body: file
      });

      if (!uploadRes.ok) throw new Error('Direct S3 upload failed.');

      setProgress(100);
      setSuccessMsg(`Files successfully uploaded! Submission ID: ${data.submission_id}`);
      setFile(null);
      setName('');
      setEmail('');
      setMessage('');
    } catch (err) {
      setErrorMsg(err.message);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Secure File Submission</h1>
        <p>Upload files securely. They are stored temporarily until reviewed and approved by the administrator.</p>
      </header>

      <form onSubmit={handleUpload} className="upload-form">
        <div className="form-group">
          <label>Your Name *</label>
          <input type="text" value={name} onChange={e => setName(e.target.value)} required placeholder="John Doe" />
        </div>

        <div className="form-group">
          <label>Email Address *</label>
          <input type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="john@example.com" />
        </div>

        <div className="form-group">
          <label>Message / Description (Optional)</label>
          <textarea value={message} onChange={e => setMessage(e.target.value)} placeholder="Notes regarding the submission..." />
        </div>

        <div className="form-group">
          <label>Select File *</label>
          <input type="file" onChange={e => setFile(e.target.files[0])} required />
          {file && <small>Selected: {file.name} ({(file.size / (1024*1024)).toFixed(2)} MB)</small>}
        </div>

        {uploading && (
          <div className="progress-bar-container">
            <div className="progress-bar" style={{ width: `${progress}%` }}></div>
            <span>{progress}% Uploaded</span>
          </div>
        )}

        {errorMsg && <div className="alert error">{errorMsg}</div>}
        {successMsg && <div className="alert success">{successMsg}</div>}

        <button type="submit" disabled={uploading} className="submit-btn">
          {uploading ? 'Uploading...' : 'Submit File'}
        </button>
      </form>
    </div>
  );
}

export default App;
